 function detail(){if(S.tableBookings)return tableDetails();const b=S.rows.find(b=>b.id===S.selectedBooking);if(!b)return `<section class="sf93-detail"><p>Réservation absente de cette journée.</p>${button('close-detail','Retour à la liste')}</section>`;const note=typeof b.note==='string'?b.note.trim():'';return `<section class="sf93-detail" aria-label="Détail de la réservation"><div class="sf93-detail-heading">${button('close-detail','‹ Liste des réservations')}<span class="sf93-status-badge ${b.status==='confirmed'?'confirmed':''}">${b.status==='confirmed'?'Confirmée':'Annulée'}</span></div><h3>${esc(b.contact_name)}</h3><p class="sf93-detail-slot">${esc(M.belgian(M.local(b.starts_at).slice(0,10)))} · ${esc(displayInterval(b))}</p><p class="sf93-presence">${presence(b)}${b.presence_state==='departed'?' · attribution conservée dans l’historique':''}</p><p class="sf93-detail-tables">${esc(M.tableSummary(M.ids(b),S.data))}</p><p>${b.covers} couverts${b.source==='web'?' · En ligne':''}</p>${b.phone?`<p>Téléphone : ${esc(b.phone)}</p>`:''}${b.email?`<p>E-mail : ${esc(b.email)}</p>`:''}${note?`<section class="sf93-note-content"><strong>Note pour l’équipe</strong><p>${esc(note)}</p></section>`:''}${S.bookingAccess.can_manage&&b.status==='confirmed'?`<div class="sf93-detail-actions">${button('edit','Modifier',b.id)}${b.presence_state!=='departed'?button('place',M.ids(b).length?'Modifier le placement':'⚠ À placer',b.id):''}${b.presence_state!=='departed'?button('presence',b.presence_state==='arrived'?'Marquer Parti':'Marquer Arrivé',b.id):''}${b.presence_state==='expected'||!b.presence_state?button('depart','Marquer Parti',b.id):''}${button('cancel','Annuler la réservation',b.id)}</div>`:''}</section>`}
