 async function prepareManual(payload,valid){const identity=S.key,epoch=S.seq;let evidence;S.busy=true;render();try{evidence=await rpc('reservations_service_preview',{p_est:S.est,p_payload:payload});if(!current(identity)||epoch!==S.seq||!valid())return false;if(evidence.reservations.length||evidence.capacity<evidence.covers){const detail=evidence.reservations.map(x=>x.name+' · '+displayInterval({starts_at:x.start,ends_at:x.end,departure_explicit:!!x.end})+' · '+x.covers+' couverts — '+(x.overlap===true?'chevauchement horaire':x.overlap===false?'horaires successifs':'départ non communiqué')).join('\n');const consent=await ask('Capacité physique : '+evidence.capacity+' places pour '+evidence.covers+' couverts.\n'+detail+'\nConfirmer explicitement ce partage ou cette capacité ?',{title:'Placement à confirmer',accept:'Confirmer le partage'});if(!consent||!current(identity)||epoch!==S.seq||!valid())return false;payload.shared_confirmed=true;}else payload.shared_confirmed=false;payload.confirmation=evidence.token;return true;}finally{if(current(identity)&&epoch===S.seq){S.busy=false;render();}}}
